extracted_python_code:
faang_tickers = ('AMZN', 'AAPL', 'GOOGL', 'META', 'NFLX')

result = Broker.CALCULATE(
    faang_buyers_count=COUNT(
        Customers.WHERE(
            (ENDSWITH(email, '.com')) &
            (HAS(transactions_made.WHERE(ISIN(ticker.symbol, faang_tickers))) == 1)
        )
    )
)

result = Customers.WHERE(
    (status == 'Active') & (join_date >= '2023-01-01')
).PARTITION(
    name='country_group', by=country
).CALCULATE(
    country=country,
    TAC=COUNT(Customers)
)

top_2_bought_tickers = Transactions.WHERE(
    (transaction_type == 'buy') & (DATEDIFF("days", date_time, 'now') <= 10)
).CALCULATE(
    ticker_symbol=ticker.symbol
).PARTITION(
    name="ticker_groups", by=(ticker_symbol)
).CALCULATE(
    ticker_symbol=ticker_symbol,
    num_buy_transactions=COUNT(Transactions)
).TOP_K(2, by=num_buy_transactions.DESC())

customers_for_ar = Customers.WHERE(
    (YEAR(join_date) == 2022) & (HAS(transactions_made) == 1)
).CALCULATE(
    country=country,
    is_active=(status == 'active')
)

activity_ratio_by_country = customers_for_ar.PARTITION(name="country_group", by=(country)).CALCULATE(
    country=country,
    AR=(SUM(Customers.is_active) / COUNT(Customers)) * 100.0
)

result = Transactions.WHERE(
    (date_time >= "2023-01-01") & (date_time <= "2023-03-31")
).PARTITION(
    name="type_groups", by=(transaction_type)
).CALCULATE(
    transaction_type=transaction_type,
    num_distinct_customers=NDISTINCT(Transactions.customer._id),
    avg_shares=AVG(Transactions.shares)
).TOP_K(3, by=num_distinct_customers.DESC())

distinct_ticker_ids = DailyPrices.WHERE(date >= "2023-04-01").PARTITION(name="distinct_tickers", by=ticker_id).CALCULATE(
    ticker_id=ticker_id
)

result = Broker.CALCULATE(
    num_transactions=COUNT(Transactions.WHERE(DATEDIFF("days", customer.join_date, DATETIME('now')) <= 70))
)

result = Customers.CALCULATE(
    _id=_id,
    name=name,
    number_of_transactions=COUNT(
        transactions_made.WHERE(
            (transaction_type == 'sell') & 
            (DATEDIFF("days", date_time, "2023-04-01") == 0)
        )
    )
).WHERE(number_of_transactions > 0).TOP_K(1, by=number_of_transactions.DESC())

sales_by_model = Cars.WHERE(
    LIKE(UPPER(vin_number), '%M5%')
).PARTITION(
    name="car_models", by=(make, model)
).CALCULATE(
    make=make,
    model=model,
    num_sales=COUNT(Cars.sale_records)
)

result = Dealership.CALCULATE(
    avg_days_to_payment=ROUND(
        AVG(
            PaymentsReceived.CALCULATE(
                days_diff=DATEDIFF("days", sale_record.sale_date, payment_date)
            ).days_diff
        ),
        2
    )
)

gpm_2023 = Dealership.CALCULATE(
    total_revenue=SUM(Sales.WHERE(YEAR(sale_date) == 2023).sale_price),
    total_cost=SUM(Sales.WHERE(YEAR(sale_date) == 2023).car.cost)
).CALCULATE(
    gpm=((total_revenue - total_cost) / total_cost) * 100
)

highest_priced_car = Sales.WHERE(
    HAS(car.inventory_snapshots.WHERE((snapshot_date == sale_date) & (is_in_inventory == False))) == 1
).TOP_K(
    1, by=sale_price.DESC()
).CALCULATE(
    make=car.make,
    model=car.model,
    sale_price=sale_price
)

result = Dealership.CALCULATE(
    TSC=COUNT(Sales.WHERE(
        (DATEDIFF("days", sale_date, DATETIME('now')) < 7) & (DATEDIFF("days", sale_date, DATETIME('now')) >= 0)
    ))
)

result = Customers.WHERE(HAS(car_purchases) == 1).CALCULATE(
    customer_id=_id
)

cash_salespersons = Salespersons.WHERE(
    HAS(sales_made.payment.WHERE(payment_method == 'Cash')) == 1
).CALCULATE(
    salesperson_id=_id
)

result = Salespersons.CALCULATE(
    first_name=first_name,
    last_name=last_name,
    total_sales_count=COUNT(sales_made.WHERE(DATEDIFF("days", sale_date, DATETIME('now')) <= 30)),
    total_revenue_amount=SUM(sales_made.WHERE(DATEDIFF("days", sale_date, DATETIME('now')) <= 30).sale_price)
).WHERE(
    total_sales_count > 0
).TOP_K(
    5, by=total_sales_count.DESC()
)

quarterly_sales_by_state = Sales.WHERE(YEAR(sale_date) == 2023).CALCULATE(
    customer_state=customer.state,
    quarter_start_date=IFF(
        MONTH(sale_date) <= 3, "2023-01-01",
        IFF(MONTH(sale_date) <= 6, "2023-04-01",
            IFF(MONTH(sale_date) <= 9, "2023-07-01", "2023-10-01")
        )
    )
).PARTITION(
    name="state_quarter_groups",
    by=(customer_state, quarter_start_date)
).CALCULATE(
    state=customer_state,
    quarter=quarter_start_date,
    total_sales=SUM(Sales.sale_price)
)

cars_in_inventory_latest_snapshot = Dealership.CALCULATE(
    latest_date=MAX(
        InventorySnapshots.WHERE(
            (YEAR(snapshot_date) == 2023) & (MONTH(snapshot_date) == 3)
        ).snapshot_date
    )
).InventorySnapshots.WHERE(
    (snapshot_date == latest_date) & (is_in_inventory == True)
).car.CALCULATE(
    _id=_id,
    make=make,
    model=model,
    year=year
)

gmail_or_yahoo_patients_count = DermTreatment.CALCULATE(
    num_patients=COUNT(
        Patients.WHERE(
            ENDSWITH(email, "@gmail.com") | ENDSWITH(email, "@yahoo.com")
        )
    )
)

filtered_patients_count = DermTreatment.CALCULATE(
    num_patients=COUNT(
        Patients.WHERE(
            HAS(
                treatments_received.WHERE(
                    (diagnosis.diag_name == 'Psoriasis vulgaris') & (drug.drug_type == 'biologic')
                )
            ) == 1
        )
    )
)

alice_treatment_count = DermTreatment.CALCULATE(
    num_treatments=COUNT(
        Patients.WHERE(first_name == "Alice").treatments_received.WHERE(
            (start_dt >= DATETIME('now', 'start of month', '-6 months')) &
            (start_dt < DATETIME('now', 'start of month'))
        )
    )
)

avg_patient_weight = Drugs.WHERE(drug_name == 'Drugalin').CALCULATE(
    avg_weight=AVG(treatments_used_in.patient.weight_kg)
)

caw_male_patients = DermTreatment.CALCULATE(
    caw=AVG(Patients.WHERE(gender == 'Male').weight_kg)
)

private_insured_patient_count = DermTreatment.CALCULATE(
    PIC=COUNT(Patients.WHERE((gender == 'F') & (ins_type == 'private')))
)

result = Drugs.WHERE(drug_type == 'biologic').treatments_used_in.doctor.PARTITION(name="states", by=loc_state).CALCULATE(
    state=loc_state
).ORDER_BY(loc_state.ASC())

pasi_score_by_insurance = Treatments.WHERE(
    YEAR(end_dt) == 2022
).CALCULATE(
    insurance_type=patient.ins_type
).PARTITION(
    name="insurance_groups", by=(insurance_type)
).CALCULATE(
    ins_type=insurance_type,
    avg_pasi_score_day_100=AVG(Treatments.outcome_records.day100_pasi_score),
    num_distinct_patients=NDISTINCT(Treatments.patient.patient_id)
).TOP_K(5, by=avg_pasi_score_day_100.ASC())

top_specialties_by_drug_amount = Treatments.WHERE(
    start_dt >= DATETIME('now', '-6 months')
).CALCULATE(
    speciality=doctor.speciality
).PARTITION(
    name="specialty_groups", by=(speciality)
).CALCULATE(
    speciality=speciality,
    number_of_treatments=COUNT(Treatments),
    total_drug_amount=SUM(Treatments.tot_drug_amt)
).TOP_K(3, by=total_drug_amount.DESC())

recent_psoriasis_treatments_count = DermTreatment.CALCULATE(
    num_treatments=COUNT(
        Treatments.WHERE(
            (LIKE(LOWER(diagnosis.diag_name), '%psoriasis%')) &
            (HAS(drug.fda_appr_dt) == 1) &
            (DATEDIFF("months", end_dt, DATETIME('now')) <= 6) &
            (end_dt <= DATETIME('now'))
        )
    )
)

avg_age_of_male_patients_with_private_insurance = DermTreatment.CALCULATE(
    avg_male_patient_age=AVG(
        Patients.WHERE(
            (gender == 'male') & (ins_type == 'private')
        ).CALCULATE(
            age=DATEDIFF("years", date_of_birth, 'now')
        ).age
    )
)

cpur_by_merchant = Merchants.WHERE(
    HAS(transactions_received.WHERE(status == 'completed')) == 1
).CALCULATE(
    merchant_name=name,
    CPUR=NDISTINCT(transactions_received.WHERE(status == 'completed').coupon_id) / COUNT(transactions_received.WHERE(status == 'completed'))
)

us_users_with_unread_promos = Users.WHERE(
    (LOWER(country) == 'us') &
    (HAS(notifications.WHERE((notification_type == 'promotional') & (status == 'unread'))) == 1)
).CALCULATE(
    username=username,
    total_unread_promotional_notifications=COUNT(
        notifications.WHERE((notification_type == 'promotional') & (status == 'unread'))
    )
)

result = Transactions.WHERE(
    (YEAR(created_at) == 2023) &
    (sender_type == 'user') &
    (status == 'completed')
).CALCULATE(
    month_date=DATETIME(created_at, 'start of month')
).PARTITION(
    name="monthly_transactions", by=(month_date)
).CALCULATE(
    month=month_date,
    num_active_users=NDISTINCT(Transactions.sender_id)
).ORDER_BY(
    month.ASC()
)

distinct_user_ids_with_transaction_notifications = Notifications.WHERE(notification_type == 'transaction').PARTITION(name="distinct_users", by=(user_id)).CALCULATE(
    user_id=user_id
)

result = UserSessions.PARTITION(name="sessions_by_device", by=(device_type)).CALCULATE(
    device_type=device_type,
    avg_session_duration_seconds=AVG(
        DATEDIFF("seconds", sessions_by_device.session_start_ts, sessions_by_device.session_end_ts)
    )
)

merchants_with_early_coupons = Merchants.WHERE(
    HAS(coupons) == 1
).CALCULATE(
    earliest_coupon=coupons.WHERE(RANKING(by=start_date.ASC(), per="Merchants", allow_ties=True) == 1).SINGULAR()
).WHERE(
    DATEDIFF("days", created_at, earliest_coupon.start_date) <= 365
).CALCULATE(
    merchant_id=mid,
    registration_date=created_at,
    earliest_coupon_id=earliest_coupon.cid,
    earliest_coupon_start_date=earliest_coupon.start_date
)
